python3 -c "
import json
with open('/app/resources/treasury_bulletin_2014_12.json', 'r') as f:
    data = json.load(f)

# Find tables with financing data
def find_financing_tables(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_financing_tables(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_financing_tables(item, f'{path}[{i}]')
    elif isinstance(obj, str):
        if 'financing' in obj.lower() or 'total' in obj.lower():
            print(f'{path}: {obj[:100]}')

find_financing_tables(data)
"
